def execute_verified(policy, verifier, obs, threshold):
    z = policy.encode(obs)                 # task-conditioned representation
    chunk = policy.propose(obs)            # actions for several future steps
    for prefix in longest_first(prefixes(chunk)):
        if verifier.validity(z, prefix) >= threshold:
            return prefix                  # commit only this far
    return shortest(prefixes(chunk))       # trust a single step, then re-query
